import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * What the customer list is narrowed down to.
 *
 * <p>Both parts are applied by {@link CustomerRepository}, never by the caller:
 * the backend is what knows how many customers match and which ones belong on
 * the page being asked for.
 *
 * @param name     free text; split on whitespace into terms, each of which must
 *                 occur in a customer's first or last name. Blank matches every
 *                 customer
 * @param statuses the statuses to keep; empty matches every customer
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    /** Combining marks left behind by NFD decomposition, e.g. the dots of "ä". */
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** The filter that keeps every customer. */
    public static CustomerFilter none() {
        return NONE;
    }

    /** {@code true} when this filter keeps every customer. */
    public boolean isEmpty() {
        return nameTerms().isEmpty() && statuses.isEmpty();
    }

    /**
     * The name filter as normalized terms, in the order they were typed.
     * Leading, trailing and repeated whitespace produces no terms of its own.
     */
    public List<String> nameTerms() {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return WHITESPACE.splitAsStream(trimmed).map(CustomerFilter::normalize).toList();
    }

    /** The selected statuses in {@link CustomerStatus} declaration order. */
    public List<CustomerStatus> orderedStatuses() {
        return java.util.Arrays.stream(CustomerStatus.values()).filter(statuses::contains).toList();
    }

    /**
     * Folds a string down to what matching compares: lower case, without
     * accents, so that {@code makinen}, {@code MAKINEN} and {@code mäkinen} all
     * come out as {@code makinen}.
     */
    public static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
