        queryLog.clear();
        nameField().pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(40));

        PlaywrightAssertions.assertThat(summary()).hasText("Showing 8 of 500");
        page.waitForURL(Pattern.compile(".*\\?name=virtanen$"));

