        nameField().blur();
        PlaywrightAssertions.assertThat(summary()).hasText("Showing 15 of 500");

        page.locator("vaadin-multi-select-combo-box").click();
        page.locator("vaadin-multi-select-combo-box-item").filter(
                new Locator.FilterOptions().setHasText("ACTIVE")).first().click();
        page.locator("vaadin-multi-select-combo-box-item").filter(
                new Locator.FilterOptions().setHasText("CLOSED")).first().click();
        page.keyboard().press("Escape");

        PlaywrightAssertions.assertThat(summary()).hasText("Showing 10 of 500");
        page.waitForURL(Pattern.compile(".*\\?name=vir&status=ACTIVE,CLOSED$"));
    }

    @Test
    void clearingTheFilterLeavesNoParametersBehind() {
        nameField().fill("vir");
        nameField().blur();
        page.waitForURL(Pattern.compile(".*\\?name=vir$"));

        nameField().fill("");
        nameField().blur();

        PlaywrightAssertions.assertThat(summary()).hasText("Showing 500 of 500");
        page.waitForURL(url -> !url.contains("?"));
    }

    @Test
    void aSharedLinkOpensTheNarrowedList() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");

        PlaywrightAssertions.assertThat(summary()).hasText("Showing 10 of 500");
        PlaywrightAssertions.assertThat(nameField()).hasValue("vir");
        assertEquals(2, page.locator(
                "vaadin-multi-select-combo-box vaadin-multi-select-combo-box-chip").count());
    }

    private Locator nameField() {
        return page.locator("vaadin-text-field input");
    }

    private Locator summary() {
        return page.getByText(Pattern.compile("^Showing \\d+ of \\d+$"));
    }
